@startuml

class Airline {
  + ID
}

class Flight {
  + ID
  + departure_time
  + arrival_time
}

class Airport {
  + ID
}

class Aircraft {
  + working_state
  + landed
  + airborne
}

class AircraftType {
  + name
}

class Pilot {
  + experience_level
}

class Captain extends Pilot {}
class CoPilot extends Pilot {}
class Navigator extends Pilot {}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives to
Flight "*" -- "1" AircraftType : uses
Aircraft "*" -- "1" AircraftType : is of type
Flight "1" -- "1" Captain : has
Flight "1" -- "1" CoPilot : has
AircraftType "1" -- "1..* " Captain : needs
AircraftType "1" -- "1..* " CoPilot : needs
AircraftType "1" -- "*" Navigator : needs

@enduml

